// wait for both: the stage on screen, and the changes (or the news that the backend can't be reached)
if (!Inputs.stage || (Inputs.changes === undefined && !Inputs.unreachable)) return;
const CACHE = 'gala-grownups-last-known';
let records;
if (Inputs.changes !== undefined) {
  records = Inputs.changes.map(Scripts.editing.plainRecord);
  try { localStorage.setItem(CACHE, JSON.stringify(records)); } catch (e) { /* storage blocked: nothing to keep */ }
} else {
  try { records = JSON.parse(localStorage.getItem(CACHE) || '[]'); } catch (e) { records = []; }
}
const data = await import('/gala-rules/src/data.js');
const { over, skipped } = Scripts.rows.buildOverrides(records, data);
if (skipped.length) console.warn('Grown-ups\' changes left out:', skipped);
const game = await import('/game/src/boot.js');
await game.boot(Inputs.stage.getDOMElement(), { over, onGrownUps: () => Outputs.openGrownUps() });
Outputs.started = true;
